func menuRowsFrom(collected map[string]interface{}, path string) ([]interface{}, bool) {
    raw := datahelpers.ExtractNestedField(collected, path)
    rows, ok := raw.([]interface{}); if !ok || len(rows) == 0 { return nil, false }
    return rows, true }

func (r *componentNameResolver) addMenu(rows []interface{}) int {
    for _, raw := range rows {
        row, ok := raw.(map[string]interface{}); if !ok { continue }
        fn := strings.TrimSpace(row["function"].(string)); if fn == "" { continue }
        if !r.validFunctions[fn] { r.validFunctions[fn] = true; r.menuOnly[fn] = true; added++ }
        // name/display_name added only if the base has not already claimed them
    }
    return added }

resolver := loadComponentNameResolver(ctx, params.DB, params.Logger)
if menuField, _ := config["menu_field"].(string); menuField != "" {
    if rows, ok := menuRowsFrom(params.CollectedData, menuField); ok {
        added := resolver.addMenu(rows)
        params.Logger.Info("ValidateSitePlanAction: accepting the planner's own component menu", ...)
    } else {
        params.Logger.Warn("... menu_field configured but no component menu at that path — falling back to the section/element base", ...)
    }
}

BEGIN; SELECT snapshot_agent('build-site-planner','439: pre-update');
UPDATE agent_definitions SET default_config = jsonb_set(default_config,
  '{workflow,steps,validate_plan,config,menu_field}', to_jsonb('available_components'::text))
 WHERE type='build-site-planner' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
DO $$ ... IF menu_source IS DISTINCT FROM menu_field THEN RAISE EXCEPTION '439: menu_field (%) does not name load_components.output_field (%)', menu_field, menu_source; END IF; END $$; COMMIT;
